initJs:
function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORES_TABLE = 1;
  const PRODUCTS_TABLE = 2;
  const DEMAND_FORECAST_TABLE = 9;
  const ORDER_TABLE = 11;

  let currentStoreId = '';
  let currentOrderDate = '';
  let currentCategoryFilter = '';
  let orderItems = [];
  let selectedItems = new Set();

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;
  currentOrderDate = today;

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 成功メッセージ表示関数
  function showSuccess(message) {
    const successDiv = container.querySelector('#order-success-message');
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');
    setTimeout(() => {
      successDiv.classList.add('hidden');
    }, 3000);
  }

  // 店舗ドロップダウン初期化
  async function initStoreDropdown() {
    try {
      const stores = await window.aivicApi.list(STORES_TABLE);
      const storeSelect = container.querySelector('#store-select');

      if (stores && stores.length > 0) {
        stores.filter(store => store.有効フラグ).forEach(store => {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('店舗データの取得に失敗しました:', error);
    }
  }

  // カテゴリフィルター初期化
  async function initCategoryFilter() {
    try {
      const products = await window.aivicApi.list(PRODUCTS_TABLE);
      const categorySelect = container.querySelector('#category-filter');

      if (products && products.length > 0) {
        const categories = [...new Set(products.map(p => p.商品カテゴリID))];
        categories.forEach(categoryId => {
          if (categoryId) {
            const option = document.createElement('option');
            option.value = categoryId;
            option.textContent = `カテゴリ ${categoryId}`;
            categorySelect.appendChild(option);
          }
        });
      }
    } catch (error) {
      console.error('カテゴリデータの取得に失敗しました:', error);
    }
  }

  // 発注アイテム一覧再描画
  function renderOrderItems(items) {
    const tbody = container.querySelector('#order-items-tbody');

    if (!items || items.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="10" style="text-align: center; padding: 40px; color: var(--text-muted);">
            ${currentStoreId ? 'データがありません' : '店舗を選択してください'}
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = items.map(item => `
      <tr data-id="${item.商品ID}">
        <td style="text-align: center;">
          <input type="checkbox" class="item-checkbox" data-id="${item.商品ID}" ${selectedItems.has(item.商品ID) ? 'checked' : ''}>
        </td>
        <td>${item.商品コード || ''}</td>
        <td>${item.商品名 || ''}</td>
        <td style="text-align: right;">${item.予測数量 || 0}</td>
        <td style="text-align: right;">${item.推奨発注数量 || 0}</td>
        <td style="text-align: right;">${item.現在在庫数量 || 0}</td>
        <td>
          <input type="number" class="input order-quantity-input" data-id="${item.商品ID}" 
                 value="${item.発注数量 || item.推奨発注数量 || 0}" min="0" max="99999" 
                 style="width: 100px; text-align: right;">
        </td>
        <td style="text-align: right;">¥${(item.単価 || 0).toLocaleString()}</td>
        <td style="text-align: right;" class="order-amount" data-id="${item.商品ID}">
          ¥${((item.発注数量 || item.推奨発注数量 || 0) * (item.単価 || 0)).toLocaleString()}
        </td>
        <td>
          <button class="action-btn secondary single-order-btn" data-id="${item.商品ID}">発注</button>
        </td>
      </tr>
    `).join('');

    updateTotalAmount();
    updateBulkOrderButton();
  }

  // 合計金額更新
  function updateTotalAmount() {
    let total = 0;
    const selectedItemsArray = Array.from(selectedItems);

    selectedItemsArray.forEach(itemId => {
      const item = orderItems.find(i => i.商品ID === itemId);
      const quantityInput = container.querySelector(`input[data-id="${itemId}"]`);
      if (item && quantityInput) {
        const quantity = parseInt(quantityInput.value) || 0;
        total += quantity * (item.単価 || 0);
      }
    });

    container.querySelector('#total-amount').textContent = `合計金額: ¥${total.toLocaleString()}`;
  }

  // まとめて発注ボタンの状態更新
  function updateBulkOrderButton() {
    const bulkOrderBtn = container.querySelector('#btn-bulk-order');
    bulkOrderBtn.disabled = selectedItems.size === 0;
  }

  // 発注データ取得
  async function loadOrderItems() {
    if (!currentStoreId) {
      renderOrderItems([]);
      return;
    }

    try {
      // 需要予測結果を取得
      const forecasts = await window.aivicApi.list(DEMAND_FORECAST_TABLE);
      const products = await window.aivicApi.list(PRODUCTS_TABLE);

      if (!forecasts || !products) {
        renderOrderItems([]);
        return;
      }

      // 店舗・日付でフィルタリング
      const targetDate = new Date(currentOrderDate);
      const filteredForecasts = forecasts.filter(f => {
        const forecastDate = new Date(f.予測対象日);
        return f.店舗ID === currentStoreId && 
               forecastDate.toDateString() === targetDate.toDateString();
      });

      // 商品情報と結合
      const items = filteredForecasts.map(forecast => {
        const product = products.find(p => p.商品ID === forecast.商品ID);
        if (!product) return null;

        // カテゴリフィルター適用
        if (currentCategoryFilter && product.商品カテゴリID !== currentCategoryFilter) {
          return null;
        }

        return {
          商品ID: product.商品ID,
          商品コード: product.商品コード,
          商品名: product.商品名,
          予測数量: forecast.予測数量,
          推奨発注数量: forecast.推奨発注数量,
          現在在庫数量: Math.floor(Math.random() * 100), // 仮の在庫数
          単価: product.単価,
          発注数量: forecast.推奨発注数量
        };
      }).filter(item => item !== null);

      orderItems = items;
      renderOrderItems(items);

    } catch (error) {
      console.error('発注データの取得に失敗しました:', error);
      showError('発注データの取得に失敗しました');
    }
  }

  // バリデーション
  function validateOrderData(items) {
    const errors = [];

    if (!currentStoreId) {
      errors.push('店舗を選択してください');
    }

    if (!currentOrderDate) {
      errors.push('発注日付を選択してください');
    } else {
      const orderDate = new Date(currentOrderDate);
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      if (orderDate < today) {
        errors.push('発注日付は本日以降の日付を選択してください');
      }
    }

    if (items.length === 0) {
      errors.push('発注する商品を選択してください');
    }

    for (const item of items) {
      const quantity = item.発注数量;

      if (quantity === undefined || quantity === null || quantity === '') {
        errors.push(`${item.商品名}: 発注数量を入力してください`);
      } else if (isNaN(quantity)) {
        errors.push(`${item.商品名}: 発注数量は数値を入力してください`);
      } else if (quantity < 0) {
        errors.push(`${item.商品名}: 発注数量は正の値を入力してください`);
      } else if (quantity === 0) {
        errors.push(`${item.商品名}: 発注数量は1以上の値を入力してください`);
      } else if (quantity % 1 !== 0) {
        errors.push(`${item.商品名}: 発注数量は整数を入力してください`);
      } else if (quantity > 99999) {
        errors.push(`${item.商品名}: 発注数量は99999以下で入力してください`);
      }
    }

    return errors;
  }

  // 発注確認ダイアログ表示
  function showOrderConfirmDialog(items) {
    const dialog = container.querySelector('#order-confirm-dialog');
    const content = container.querySelector('#order-confirm-content');

    const totalAmount = items.reduce((sum, item) => sum + (item.発注数量 * item.単価), 0);

    content.innerHTML = `
      <div style="margin-bottom: 15px;">
        <strong>店舗:</strong> ${container.querySelector('#store-select option:checked').textContent}<br>
        <strong>発注日:</strong> ${currentOrderDate}<br>
        <strong>発注商品数:</strong> ${items.length}件<br>
        <strong>合計金額:</strong> ¥${totalAmount.toLocaleString()}
      </div>
      <div style="max-height: 300px; overflow-y: auto; border: 1px solid var(--border); border-radius: 4px;">
        <table style="width: 100%; font-size: 14px;">
          <thead>
            <tr style="background: var(--bg-main);">
              <th style="padding: 8px; color: var(--text);">商品名</th>
              <th style="padding: 8px; color: var(--text); text-align: right;">数量</th>
              <th style="padding: 8px; color: var(--text); text-align: right;">単価</th>
              <th style="padding: 8px; color: var(--text); text-align: right;">金額</th>
            </tr>
          </thead>
          <tbody>
            ${items.map(item => `
              <tr>
                <td style="padding: 8px; color: var(--text);">${item.商品名}</td>
                <td style="padding: 8px; color: var(--text); text-align: right;">${item.発注数量}</td>
                <td style="padding: 8px; color: var(--text); text-align: right;">¥${item.単価.toLocaleString()}</td>
                <td style="padding: 8px; color: var(--text); text-align: right;">¥${(item.発注数量 * item.単価).toLocaleString()}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;

    dialog.classList.remove('hidden');
  }

  // 発注実行
  async function executeOrder(items) {
    try {
      const orders = items.map(item => ({
        店舗ID: currentStoreId,
        商品ID: item.商品ID,
        発注日: currentOrderDate + 'T00:00:00Z',
        納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
        発注数量: item.発注数量,
        予測数量: item.予測数量,
        発注単価: item.単価,
        発注金額: item.発注数量 * item.単価,
        発注方法: 'AI推奨採用',
        発注ステータス: '発注済',
        仕入先ID: 'supplier-001',
        発注理由: 'AI需要予測に基づく発注',
        自動発注フラグ: false,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString(),
        作成者ID: 'current-user',
        更新者ID: 'current-user'
      }));

      // 各発注を個別に保存
      for (const order of orders) {
        await window.aivicApi.save(ORDER_TABLE, order);
      }

      // 成功メッセージ表示
      showSuccess(`${items.length}件の商品を発注しました`);

      // 選択状態をクリア
      selectedItems.clear();

      // データを再読み込み
      await loadOrderItems();

    } catch (error) {
      console.error('発注処理に失敗しました:', error);
      showError('発注処理に失敗しました');
    }
  }

  // イベントリスナー設定

  // 店舗選択
  container.querySelector('#store-select').addEventListener('change', async (e) => {
    currentStoreId = e.target.value;
    selectedItems.clear();
    await loadOrderItems();
  });

  // 発注日付選択
  container.querySelector('#order-date').addEventListener('change', async (e) => {
    currentOrderDate = e.target.value;
    await loadOrderItems();
  });

  // カテゴリフィルター
  container.querySelector('#category-filter').addEventListener('change', async (e) => {
    currentCategoryFilter = e.target.value;
    await loadOrderItems();
  });

  // 検索・更新ボタン
  container.querySelector('#btn-search').addEventListener('click', async () => {
    await loadOrderItems();
  });

  // 全選択チェックボックス
  container.querySelector('#select-all-checkbox').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.item-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedItems.add(cb.dataset.id);
      } else {
        selectedItems.delete(cb.dataset.id);
      }
    });
    container.querySelector('#selected-count').textContent = `選択: ${selectedItems.size}件`;
    updateTotalAmount();
    updateBulkOrderButton();
  });

  // まとめて発注実行ボタン
  container.querySelector('#btn-bulk-order').addEventListener('click', () => {
    const selectedOrderItems = [];

    selectedItems.forEach(itemId => {
      const item = orderItems.find(i => i.商品ID === itemId);
      const quantityInput = container.querySelector(`input[data-id="${itemId}"]`);

      if (item && quantityInput) {
        const quantity = parseInt(quantityInput.value) || 0;
        selectedOrderItems.push({
          ...item,
          発注数量: quantity
        });
      }
    });

    const errors = validateOrderData(selectedOrderItems);
    if (errors.length > 0) {
      showError(errors.join('\n'));
      return;
    }

    showOrderConfirmDialog(selectedOrderItems);
  });

  // 発注確認ダイアログのイベント
  container.querySelector('#btn-cancel-order').addEventListener('click', () => {
    container.querySelector('#order-confirm-dialog').classList.add('hidden');
  });

  container.querySelector('#btn-execute-order').addEventListener('click', async () => {
    container.querySelector('#order-confirm-dialog').classList.add('hidden');

    const selectedOrderItems = [];
    selectedItems.forEach(itemId => {
      const item = orderItems.find(i => i.商品ID === itemId);
      const quantityInput = container.querySelector(`input[data-id="${itemId}"]`);

      if (item && quantityInput) {
        const quantity = parseInt(quantityInput.value) || 0;
        selectedOrderItems.push({
          ...item,
          発注数量: quantity
        });
      }
    });

    await executeOrder(selectedOrderItems);
  });

  // イベントデリゲーション
  container.addEventListener('change', (e) => {
    // 個別チェックボックス
    if (e.target.classList.contains('item-checkbox')) {
      const itemId = e.target.dataset.id;
      if (e.target.checked) {
        selectedItems.add(itemId);
      } else {
        selectedItems.delete(itemId);
      }

      container.querySelector('#selected-count').textContent = `選択: ${selectedItems.size}件`;

      // 全選択チェックボックスの状態更新
      const allCheckboxes = container.querySelectorAll('.item-checkbox');
      const checkedCount = container.querySelectorAll('.item-checkbox:checked').length;
      const selectAllCheckbox = container.querySelector('#select-all-checkbox');
      selectAllCheckbox.checked = checkedCount === allCheckboxes.length;
      selectAllCheckbox.indeterminate = checkedCount > 0 && checkedCount < allCheckboxes.length;

      updateTotalAmount();
      updateBulkOrderButton();
    }

    // 発注数量入力
    if (e.target.classList.contains('order-quantity-input')) {
      const itemId = e.target.dataset.id;
      const quantity = parseInt(e.target.value) || 0;
      const item = orderItems.find(i => i.商品ID === itemId);

      if (item) {
        const amount = quantity * item.単価;
        const amountCell = container.querySelector(`.order-amount[data-id="${itemId}"]`);
        if (amountCell) {
          amountCell.textContent = `¥${amount.toLocaleString()}`;
        }
      }

      updateTotalAmount();
    }
  });

  container.addEventListener('click', async (e) => {
    // 個別発注ボタン
    if (e.target.classList.contains('single-order-btn')) {
      const itemId = e.target.dataset.id;
      const item = orderItems.find(i => i.商品ID === itemId);
      const quantityInput = container.querySelector(`input[data-id="${itemId}"]`);

      if (item && quantityInput) {
        const quantity = parseInt(quantityInput.value) || 0;
        const orderItem = {
          ...item,
          発注数量: quantity
        };

        const errors = validateOrderData([orderItem]);
        if (errors.length > 0) {
          showError(errors.join('\n'));
          return;
        }

        showOrderConfirmDialog([orderItem]);
      }
    }
  });

  // 初期化
  initStoreDropdown();
  initCategoryFilter();
}
